<script lang="ts">
  import { TreeSelect, Form, FormItem, Button, createForm, type TreeSelectValue, type TreeSelectNode, type TreeKey } from '../../src/lib/components/ant-design';
  const initial: TreeSelectNode[]=[{value:'p',title:'Parent',children:[{value:'a',title:'Alpha'},{value:'b',title:'Beta'},{value:'locked',title:'Locked',disabled:true}]},{value:0,title:'Zero'},{value:'branch',title:'Branch',children:[{value:'c',title:'Gamma'}]}];
  let data=$state.raw(initial);let deferredData=$state.raw<TreeSelectNode[]>([]);let uncontrolledEvents=$state<string[]>([]);let value=$state<TreeSelectValue>('a');let checkable=$state(false);let strict=$state(false);let multiple=$state(false);let labeled=$state(false);let accept=$state(true);let strategy=$state<'SHOW_ALL'|'SHOW_PARENT'|'SHOW_CHILD'>('SHOW_CHILD');
  let lockClosed=$state(false);let openings=$state<boolean[]>([]);let scrolls=$state(0);
  let search=$state('');let keepSearch=$state(false);let filter=$state(true);let events=$state<string[]>([]);let selects=$state<string[]>([]);let native=$state('');
  let lazyData=$state.raw<TreeSelectNode[]>([{value:'lazy',title:'Lazy',isLeaf:false}]);let loaded=$state<TreeKey[]>([]);let calls=$state(0);let pending:{resolve:()=>void;reject:(error:Error)=>void}|undefined;
  const form=createForm<{parent:string|undefined}>({initialValues:{parent:undefined},rules:{parent:[{required:true,message:'Choose a parent'}]}});let submitted=$state('');
</script>
<section id="tree-select-fixture" aria-label="TreeSelect fixture">
  <form onsubmit={event=>{event.preventDefault();native=JSON.stringify(new FormData(event.currentTarget).getAll('parent'));}}>
    <TreeSelect aria-label="Parent select" name="parent" listHeight={96} open={lockClosed?false:undefined} onOpenChange={next=>{openings=[...openings,next];}} onPopupScroll={()=>{scrolls++;}} treeData={data} {value} treeCheckable={checkable} treeCheckStrictly={strict} {multiple} labelInValue={labeled} showCheckedStrategy={strategy} treeDefaultExpandAll allowClear showSearch={{searchValue:search,onSearch:next=>{search=next;},treeNodeFilterProp:'title',filterTreeNode:filter,autoClearSearchValue:!keepSearch}} onChange={(next,labels,extra)=>{events=[...events,JSON.stringify({value:next??null,labels,extra})];if(accept)value=next;}} onSelect={raw=>{selects=[...selects,`select:${raw}`];}} onDeselect={raw=>{selects=[...selects,`deselect:${raw}`];}} />
    <button type="submit">Read tree select FormData</button>
  </form>
  <TreeSelect aria-label="Lazy select" treeData={lazyData} treeLoadedKeys={loaded} onTreeLoad={keys=>{loaded=keys;}} showSearch={{treeNodeFilterProp:'title'}} loadData={()=>{calls++;return new Promise<void>((resolve,reject)=>{pending={resolve,reject};});}} />
  <TreeSelect aria-label="Uncontrolled search" onChange={(next,labels,extra)=>{uncontrolledEvents=[...uncontrolledEvents,JSON.stringify({value:next,labels,extra})];}} treeData={initial} multiple showSearch treeDefaultExpandAll />
  <TreeSelect aria-label="Deferred select" treeData={deferredData} treeDefaultExpandAll />
  <button type="button" onclick={()=>{deferredData=initial;}}>Load deferred tree data</button>
  <button type="button" onclick={()=>{value=[{value:'p',label:'Parent',halfChecked:true},{value:'a',label:'Alpha'}];}}>Set strict half owner</button>
  <output aria-label="Uncontrolled changes">{JSON.stringify(uncontrolledEvents)}</output>
  <TreeSelect aria-label="Default select" treeData={initial} defaultValue={0} treeDefaultExpandAll allowClear />
  <Form {form} onFinish={values=>{submitted=String(values.parent);}}><FormItem name="parent" label="Form parent"><TreeSelect treeData={initial} value={form.values.parent} treeDefaultExpandAll allowClear onChange={next=>form.setFieldValue('parent',next)} /></FormItem><Button htmlType="submit">Submit tree select</Button><Button htmlType="reset">Reset tree select</Button></Form>
  <label><input type="checkbox" bind:checked={lockClosed} /> Lock tree select closed</label>
  <label><input type="checkbox" bind:checked={checkable} /> Tree select checkable</label><label><input type="checkbox" bind:checked={strict} /> Tree select strict</label><label><input type="checkbox" bind:checked={multiple} /> Tree select multiple</label><label><input type="checkbox" bind:checked={labeled} /> Tree select labeled</label><label><input type="checkbox" bind:checked={accept} /> Accept tree select changes</label><label><input type="checkbox" bind:checked={keepSearch} /> Keep tree select search</label><label><input type="checkbox" bind:checked={filter} /> Filter tree select</label>
  <select aria-label="Tree select strategy" bind:value={strategy}><option value="SHOW_CHILD">SHOW_CHILD</option><option value="SHOW_PARENT">SHOW_PARENT</option><option value="SHOW_ALL">SHOW_ALL</option></select>
  <button type="button" onclick={()=>{value=null;search='';}}>Clear tree select owner</button><button type="button" onclick={()=>{data=[];}}>Remove tree select data</button><button type="button" onclick={()=>{data=initial;}}>Restore tree select data</button>
  <button type="button" onclick={()=>{lazyData=[{...lazyData[0],children:[{value:'loaded-child',title:'Loaded child',isLeaf:true}]}];pending?.resolve();pending=undefined;}}>Resolve tree select load</button><button type="button" onclick={()=>{pending?.reject(Error('Load failed'));pending=undefined;}}>Reject tree select load</button>
  <output aria-label="Tree select openings">{JSON.stringify(openings)}</output><output aria-label="Tree select scrolls">{scrolls}</output>
  <output aria-label="Tree select value">{JSON.stringify(value??null)}</output><output aria-label="Tree select changes">{JSON.stringify(events)}</output><output aria-label="Tree select selection events">{JSON.stringify(selects)}</output><output aria-label="Tree select search">{search}</output><output aria-label="Tree select FormData">{native}</output><output aria-label="Tree select load calls">{calls}</output><output aria-label="Tree select loaded">{JSON.stringify(loaded)}</output><output aria-label="Tree select submitted">{submitted}</output>
</section>
